   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……我记得……她真的就像故事书里的天使一样，头发长长的像黄金一样，眼睛像是蓝宝石一样美丽……", msg_color="", msg_size=0, talker="稚嫩的童声录音", audio="", img="arts/ui/bg/story/storybg_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
